// Import of required libraries
import { test, expect, SkyrampClient, getValue } from '@skyramp/skyramp';
import { get_roles, create_invite } from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Ghost " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const endpoint2GetResponse = await get_roles(client, headers);

    // Generated Assertions
    expect(endpoint2GetResponse.statusCode, 'status code').toBe(200);

    const assignableRoles = JSON.parse((endpoint2GetResponse as any).responseBody).roles;
    expect(Array.isArray(assignableRoles), 'roles is an array').toBe(true);

    expect(assignableRoles.map((role: {name: string}) => role.name), 'Owner is never assignable').not.toContain("Owner");

    const editorPlusRole = assignableRoles.find((role: {name: string}) => role.name === "Editor Plus");
    expect(editorPlusRole, 'Editor Plus is advertised as an assignable role').toBeTruthy();
    expect(editorPlusRole.description, 'Editor Plus description').toBe("Editors with extended publishing privileges");
    expect(editorPlusRole.id, 'Editor Plus id').toMatch(/^[0-9a-f]{24}$/i);
    expect(editorPlusRole.created_at, 'Editor Plus created_at').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const endpoint1PostResponse = await create_invite(client, headers, editorPlusRole.id, "editor-plus-invite@example.com");

    // The roles endpoint just advertised Editor Plus as assignable, so inviting a staff
    // member with that role must not be refused as a permission error. Ghost's invite
    // allowlist (ghost/core/core/server/models/invite.js) was never extended with the new
    // role, so this currently returns 403 while Editor and Super Editor are accepted.
    expect(endpoint1PostResponse.statusCode, 'Editor Plus invite must not be refused with a permission error').not.toBe(403);
    expect(getValue(endpoint1PostResponse, "errors.0.type"), 'invite must not fail as NoPermissionError').not.toBe("NoPermissionError");
    expect(getValue(endpoint1PostResponse, "errors.0.context"), 'invite must not be refused for lacking add-invite permission').not.toBe("You do not have permission to add invites");
});
